using System;
using System.Collections;
using System.IO;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEngine.TestTools;
namespace LastRail.Tests.EditMode {public sealed class BDepartureAssignmentHttpTests {
 const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BDepartureAssignment-20261006/";
 static IEnumerator Wait(Task t){var deadline=DateTime.UtcNow.AddSeconds(90);while(!t.IsCompleted){Assert.Less(DateTime.UtcNow,deadline);yield return null;}}
 [UnityTest,Timeout(180000)] public IEnumerator OriginalPersistedGameSourceRecoveryStaleReauthenticationAndNoBackfill(){var path=Environment.GetEnvironmentVariable("LASTRAIL_ASSIGNMENT_CONNECTION");if(string.IsNullOrEmpty(path))Assert.Ignore("Explicit disposable persisted GAME/SQL source required");var connection=JObject.Parse(File.ReadAllText(path));var token=new GameApiAccessToken((string)connection["token"]);var run=(string)connection["runId"];using(var adapter=new UnityWebRequestRunApiHttpAdapter((string)connection["origin"],20)){var raw=new GameApiAuthenticatedHttpTransport(new UnityWebRequestRunApiHttpTransport(adapter));var client=new BDepartureAssignmentHttpClient(raw);using(var c=new BRouteSessionController("a",run)){var before=c.Capture();var first=c.ReadDepartureAssignmentAsync(client,token);yield return Wait(first);Assert.IsTrue(first.GetAwaiter().GetResult());var source=c.DepartureAssignment;Assert.IsFalse(source.CanStart);Assert.AreEqual(1,source.Actors.Count);Assert.AreEqual(0,source.Actors[0].PhysicalSlot);Assert.IsNull(source.CarAtPhysicalSlot(1));Assert.AreEqual("CARGO",(string)source.CarAtPhysicalSlot(4)["occupant"]["kind"]);Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));
 var remove=raw.SendAsync(new RunApiHttpRequest("GET","/__qa_remove_current_sources",null,null),token);yield return Wait(remove);remove.GetAwaiter().GetResult();using(var restarted=new BRouteSessionController("a",run)){var recovery=restarted.ReadDepartureAssignmentAsync(client,token,source.PacketHash);yield return Wait(recovery);Assert.IsTrue(recovery.GetAwaiter().GetResult());Assert.IsTrue(JToken.DeepEquals(source.Capture(),restarted.DepartureAssignment.Capture()));}
 var errors=new JArray();var stale=client.ReadAsync("a",run,token,new string('0',64));yield return Wait(stale);var staleError=stale.Exception.GetBaseException() as BResultReportHttpException;Assert.AreEqual(409,staleError.StatusCode);errors.Add(new JObject{["name"]="IfMatch stale",["status"]=409,["code"]=staleError.ErrorCode});
 var wrongAccount=client.ReadAsync("b",run,token);yield return Wait(wrongAccount);Assert.IsInstanceOf<ArgumentException>(wrongAccount.Exception.GetBaseException());
 var historical=client.ReadAsync("a",(string)connection["legacyRunId"],token);yield return Wait(historical);var historicalError=historical.Exception.GetBaseException() as BResultReportHttpException;Assert.NotNull(historicalError);Assert.AreEqual(409,historicalError.StatusCode);errors.Add(new JObject{["name"]="historical no assignment",["status"]=409,["code"]=historicalError.ErrorCode});
 foreach(var pair in new[]{Tuple.Create("wrong-version",409),Tuple.Create("query",400)}){var send=raw.SendAsync(new RunApiHttpRequest("GET","/v1/runs/"+run+"/b-departure-assignment"+(pair.Item1=="query"?"?accountId=b":""),null,new[]{new RunApiHttpHeader("X-B-Assignment-Version",pair.Item1=="wrong-version"?"old":BDepartureAssignment.Version)}),token);yield return Wait(send);var response=send.GetAwaiter().GetResult().Response;Assert.AreEqual(pair.Item2,response.StatusCode);errors.Add(new JObject{["name"]=pair.Item1,["status"]=response.StatusCode,["code"]=RunApiErrorJsonAdapter.OptionalString(response.BodyJson,"errorCode")});}
 var revoke=raw.SendAsync(new RunApiHttpRequest("GET","/__qa_revoke",null,null),token);yield return Wait(revoke);revoke.GetAwaiter().GetResult();var revoked=client.ReadAsync("a",run,token);yield return Wait(revoked);var authError=revoked.Exception.GetBaseException() as BResultReportHttpException;Assert.AreEqual(401,authError.StatusCode);errors.Add(new JObject{["name"]="revoked original session",["status"]=401,["code"]=authError.ErrorCode});var renew=raw.SendAsync(new RunApiHttpRequest("GET","/__qa_reauthenticate",null,null),token);yield return Wait(renew);Assert.AreEqual(200,renew.GetAwaiter().GetResult().Response.StatusCode);var renewed=new GameApiAccessToken((string)JObject.Parse(File.ReadAllText(path))["token"]);var after=client.ReadAsync("a",run,renewed,source.PacketHash);yield return Wait(after);Assert.IsTrue(JToken.DeepEquals(source.Capture(),after.GetAwaiter().GetResult().Capture()));
 File.WriteAllText(Qa+"actual-http-assignment.json",new JObject{["evidence"]="ACTUAL_UNITY_GAME_TCP_DISPOSABLE_PERSISTED_SQL_ORIGINAL_B_PRODUCER_EXPLICIT_SYNTHETIC_ACCOUNT_SOURCES",["assignment"]=source.Capture(),["currentSourcesRemoved"]=true,["originalSnapshotRecovery"]=true,["sameIfMatchRecovery"]=true,["wrongAccountRejected"]=true,["reauthenticationRecovery"]=true,["controllerCaptureUnchanged"]=true,["errors"]=errors,["nativeRuntimeBound"]=false,["effectiveStatsSupported"]=false,["operatingStart"]=false}.ToString());}}
 }
